// Lo que ve el panel. Sin datos de contacto de los leads (nombre, correo, teléfono quedan en el Sheet).
const z = 'America/Mexico_City', hoy = $now.setZone(z);
const q = ($('Panel lectura').first().json.query || {});
const dias = Math.min(180, Math.max(1, Number(q.dias) || 30));
const desde = hoy.minus({ days: dias }).toFormat('yyyy-MM-dd');
const filas = n => { try { return $(n).all().map(i => i.json || {}); } catch (e) { return []; } };
const cal = filas('Calendario').filter(r => r.post_id);
const posts = cal
  .filter(r => String(r.fecha || '') >= hoy.minus({ days: 14 }).toFormat('yyyy-MM-dd'))
  .sort((a, b) => (String(a.fecha) + String(a.hora)).localeCompare(String(b.fecha) + String(b.hora)))
  .map(r => ({ post_id: r.post_id, marca: r.marca, fecha: r.fecha, hora: r.hora, tipo: r.tipo, estado: r.estado, version: r.version,
    titular: r.titular, copy: String(r.copy || '').slice(0, 900), tema: String(r.tema || '').slice(0, 600), fb_url: r.fb_url, ig_url: r.ig_url, cambios_pedidos: r.cambios_pedidos }));
const leads = filas('Leads').filter(l => l.lead_id && String(l.fecha || '') >= desde);
const porMarca = {}, porFuente = {}, porDia = {};
for (const l of leads) {
  if (l.estado === 'descartado') continue;
  porMarca[l.marca] = (porMarca[l.marca] || 0) + 1;
  const fuente = l.gclid ? 'Google Ads' : (l.fbclid || l.fbc || l.origen === 'meta_form') ? 'Meta' : l.utm_source || (l.referrer ? 'referido' : 'directo');
  porFuente[fuente] = (porFuente[fuente] || 0) + 1;
  const d = String(l.fecha).slice(0, 10); porDia[d] = (porDia[d] || 0) + 1;
}
const ultimos = leads.slice(-50).reverse().map(l => ({ fecha: l.fecha, marca: l.marca, origen: l.origen, estado: l.estado, empresa: l.empresa, tipo: l.tipo, utm_source: l.utm_source, utm_campaign: l.utm_campaign, notas: l.notas }));
const publicados = filas('Publicados').filter(p => String(p.fecha_hora || '') >= desde).length;
const articulos = filas('seo_articulos').map(a => ({ id: a.id, marca: a.marca, keyword: a.keyword, titulo: a.titulo, estado: a.estado, version: a.version, url: a.url, volumen: a.volumen, dificultad: a.dificultad, actualizado: a.actualizado }));
const hallazgos = filas('Hallazgos').filter(h => String(h.fecha || '') >= desde).slice(-40).reverse();
const campanas = filas('paid_campanas').filter(c => c.campana_id).map(c => ({ campana_id: c.campana_id, marca: c.marca, medio: c.medio, nombre: c.nombre, estado: c.estado, objetivo: c.objetivo, presupuesto: c.presupuesto, landing: c.landing, titular: c.titular, copy: String(c.copy || '').slice(0, 600), error: c.error, actualizado: c.actualizado })).sort((a, b) => String(b.actualizado).localeCompare(String(a.actualizado)));
const decisiones = filas('meta_ads_decisiones').filter(x => x.adset_id && String(x.fecha || '') >= hoy.minus({ days: 14 }).toFormat('yyyy-MM-dd')).slice(0, 60).map(x => ({ fecha: x.fecha, marca: x.marca, campana: x.campana, conjunto: x.conjunto, regla: x.regla, accion: x.accion, estado: x.estado, gasto_7d: x.gasto_7d, leads_7d: x.leads_7d, cpl_7d: x.cpl_7d, detalle: x.detalle }));
const estados = {};
for (const p of cal) estados[p.estado || 'sin estado'] = (estados[p.estado || 'sin estado'] || 0) + 1;
return [{ json: { generado: hoy.toFormat('yyyy-MM-dd HH:mm'), dias, kpis: { leads: Object.values(porMarca).reduce((a, b) => a + b, 0), publicados, por_aprobar: cal.filter(p => p.estado === 'por aprobar').length, articulos_por_aprobar: articulos.filter(a => a.estado === 'por aprobar').length }, estados, leads: { por_marca: porMarca, por_fuente: porFuente, por_dia: porDia, ultimos }, posts, articulos, hallazgos, campanas, decisiones } }];
